import{_ as t}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as r,o as e,c as i,a2 as l}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"ようこそ","description":"MiniTavern Ultra ガイド — スマホで AI ロールプレイ、キャラカード、BYOK、Ollama/LM Studio。","frontmatter":{"title":"ようこそ","description":"MiniTavern Ultra ガイド — スマホで AI ロールプレイ、キャラカード、BYOK、Ollama/LM Studio。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"ようこそ · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra ガイド — スマホで AI ロールプレイ、キャラカード、BYOK、Ollama/LM Studio。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja"}]]},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md","lastUpdated":1787224147000}'),n={name:"ja/index.md"};function o(s,a,d,u,g,h){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="ようこそ" tabindex="-1">ようこそ <a class="header-anchor" href="#ようこそ" aria-label="Permalink to &quot;ようこそ&quot;">​</a></h1><div class="overview-hero"><p><img src="'+t+'" alt="MiniTavern Ultra"></p></div><h2 id="アプリ紹介" tabindex="-1">アプリ紹介 <a class="header-anchor" href="#アプリ紹介" aria-label="Permalink to &quot;アプリ紹介&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong> は <strong>AI ロールプレイチャット</strong> アプリです。</p><p><strong>AI の相棒を作り、物語を演じる</strong> —— 一枚のカードから、好きな開き方を選んでください。</p><p>お気に入りのキャラカードを読み込み／作成し、クラウドやローカルモデルへ <strong>BYOK</strong> で接続。鍵とデータはまず端末に残ります。</p><h2 id="できること" tabindex="-1">できること <a class="header-anchor" href="#できること" aria-label="Permalink to &quot;できること&quot;">​</a></h2><ol><li><p><strong>自分だけの AI の相棒を作る</strong><br> 性格・話し方・関係性をカスタムし、「自分だけを理解してくれる」存在に。相談・寄り添い・日常の雑談に。</p></li><li><p><strong>推しや原作キャラをそばに</strong><br> コミュニティのキャラカードを取り込み（SillyTavern 系フォーマット対応）、慣れた口調で劇情や日常を続ける。</p></li><li><p><strong>一緒に物語を演じ、長編を書く</strong><br> ワールドブックで設定を安定させ、正規表現で表示を磨く。セッションごとにモデルと見た目を縛れます。</p></li><li><p><strong>自分のモデルを、自分のペースで</strong><br><strong>BYOK</strong>：API Key を自前で用意して主要サービスへ直結。自宅 PC の Ollama / LM Studio にも接続可。有料枠がないときは <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a>；本機配備は <a href="/ultra_guides/ja/local/">ローカルモデル</a>。</p></li></ol><h2 id="なぜ-minitavern-か" tabindex="-1">なぜ MiniTavern か <a class="header-anchor" href="#なぜ-minitavern-か" aria-label="Permalink to &quot;なぜ MiniTavern か&quot;">​</a></h2><ul><li><strong>一枚のカード、二つの開き方</strong>：日常の寄り添いか、役者としてのロールプレイか、同じ入口から</li><li><strong>キャラカード優先</strong>：PNG / JSON の取り込みとプレビュー、創作からチャット開始まで一本化</li><li><strong>私有 API</strong>：鍵は自分で管理、単一チャネルに縛られない</li><li><strong>上級も遊べる</strong>：ワールドブック、正規表現、ペルソナ、インタラクティブなカード面</li><li><strong>データは持ち出せる</strong>：バックアップと単聊アーカイブで機種変更も安心</li></ul><h2 id="クイックスタート" tabindex="-1">クイックスタート <a class="header-anchor" href="#クイックスタート" aria-label="Permalink to &quot;クイックスタート&quot;">​</a></h2><ol><li><strong>モデルを設定</strong>：設定 → <a href="/ultra_guides/ja/manual/model-link">モデル</a> → モデル接続 → 新規作成して接続テスト、デフォルトに。</li><li><strong>キャラを取り込む／作る</strong>：キャラカード → <a href="/ultra_guides/ja/manual/chara-card">取り込みまたは作成</a>。</li><li><strong>チャット開始</strong>：キャラから開く——寄り添いか本格ロールプレイかはあなた次第。</li></ol><p>詳細は <a href="/ultra_guides/ja/manual/getting-started">はじめての利用</a>。本機配備は左の <strong>ローカルモデル</strong>：<a href="/ultra_guides/ja/local/">概要</a> · <a href="/ultra_guides/ja/quickstart">30 分クイックスタート</a> · <a href="/ultra_guides/ja/local/image-gen/">画像生成</a>。無料枠は <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a>。</p><h2 id="ユーザーマニュアル入口" tabindex="-1">ユーザーマニュアル入口 <a class="header-anchor" href="#ユーザーマニュアル入口" aria-label="Permalink to &quot;ユーザーマニュアル入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区分</th><th>説明</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ja/manual/">マニュアルホーム</a></td><td>推奨読書順と総覧</td></tr><tr><td><a href="/ultra_guides/ja/manual/model-link">モデル</a></td><td>接続、パラメータ、接続テストとトラブルシュート</td></tr><tr><td><a href="/ultra_guides/ja/free-cloud/">無料クラウド</a></td><td>各社の無料枠と Key の記入</td></tr><tr><td><a href="/ultra_guides/ja/local/">ローカルモデル</a></td><td>言語 / 画像の本機配備</td></tr><tr><td><a href="/ultra_guides/ja/manual/chara-card">キャラ</a></td><td>取り込み、編集、チャット開始</td></tr><tr><td><a href="/ultra_guides/ja/manual/chat">チャット</a></td><td>対話とセッション設定</td></tr><tr><td><a href="/ultra_guides/ja/manual/lorebook">上級</a></td><td>ワールドブック、正規表現、ペルソナ、バックアップ</td></tr></tbody></table><p>App 内：設定 → <strong>ヘルプとフィードバック</strong> → <strong>ユーザーマニュアル</strong>。</p><h2 id="よくある質問-要約" tabindex="-1">よくある質問（要約） <a class="header-anchor" href="#よくある質問-要約" aria-label="Permalink to &quot;よくある質問（要約）&quot;">​</a></h2><p><strong>Q：MiniTavern Ultra とは？</strong><br> A：AI ロールプレイチャットアプリです。自分の AI 相棒を作ることも、キャラカードを取り込んで演じることもでき、自分の API Key やローカルモデルで対話します。</p><p><strong>Q：データは御社サーバーに上がりますか？</strong><br> A：チャット・キャラ・鍵などはデフォルトで端末内。モデル呼び出し時は、あなたが設定した第三者またはローカルアドレスへ送られます。詳しくは <a href="/ultra_guides/ja/privacy">プライバシー</a>。</p><p><strong>Q：API なしでも遊べますか？</strong><br> A：クラウド Key を自前で用意するか、<a href="/ultra_guides/ja/local/">ローカルモデル</a> で PC 上に建ててからスマホ接続が必要です。よくある無料枠は <a href="/ultra_guides/ja/free-cloud/">無料クラウド</a>；本機画像は <a href="/ultra_guides/ja/local/image-gen/">画像モデル配備</a>。</p><h2 id="ダウンロードとポリシー" tabindex="-1">ダウンロードとポリシー <a class="header-anchor" href="#ダウンロードとポリシー" aria-label="Permalink to &quot;ダウンロードとポリシー&quot;">​</a></h2><ul><li>トップバー <strong>MiniTavern をダウンロード</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">製品公式サイト</a></li><li><a href="/ultra_guides/ja/privacy">プライバシー</a> · <a href="/ultra_guides/ja/terms">利用規約</a></li></ul>',22)])])}const _=r(n,[["render",o]]);export{m as __pageData,_ as default};
